package groundtruth

// Scanner interop (plan v3 §4 P1-LAB L2): the raw Checkov and Trivy goldens for lab/terraform
// (lab/golden/<tool>/<version>/, regenerated by lab/golden/regen.sh) are ingested through the real
// adapters (`cloud-posture ingest --source checkov|trivy`) into a temp DB. lab/golden/expectations.yaml
// lists, per tool, every lab weakness the tool detects on the lab Terraform (native check + resource)
// and the canonical id nimbus must map it to.
//
//	go test ./tests/groundtruth -run Golden -v                      # known gaps (lab/known_gaps.yaml golden:) tolerated
//	GROUNDTRUTH_STRICT=1 go test ./tests/groundtruth -run Golden -v # no gaps allowed
//	GOLDEN_REPORT=/tmp/interop.md go test ./tests/groundtruth -run Golden
//
// A listed detection that is missing from the raw golden is a hard failure (the golden or the list is
// wrong). A detection that nimbus does not map to the expected canonical id is a gap: it must be listed
// in lab/known_gaps.yaml `golden:` with an owner (same gate as `gaps:`).

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

type goldenExpectation struct {
	Weakness  string `yaml:"weakness"`
	Check     string `yaml:"check"`
	Resource  string `yaml:"resource"`
	Canonical string `yaml:"canonical"`
	Note      string `yaml:"note"`
}

type goldenTool struct {
	Tool        string              `yaml:"tool"`
	Version     string              `yaml:"version"`
	Files       []string            `yaml:"files"`
	Detects     []goldenExpectation `yaml:"detects"`
	NotDetected map[string]string   `yaml:"not_detected"`
	NotInLabHCL []string            `yaml:"not_in_lab_hcl"`
}

type goldenFile struct {
	Version int          `yaml:"version"`
	Tools   []goldenTool `yaml:"tools"`
}

func (g goldenTool) dir() string { return filepath.Join("lab", "golden", g.Tool, g.Version) }

// rawFailures reads (check, resource) pairs the tool itself reported as failed in the raw golden.
func rawFailures(t *testing.T, tool string, data []byte) map[string]bool {
	t.Helper()
	out := map[string]bool{}
	switch tool {
	case "checkov":
		var reports []struct {
			Results struct {
				Failed []struct {
					CheckID  string `json:"check_id"`
					Resource string `json:"resource"`
				} `json:"failed_checks"`
			} `json:"results"`
		}
		trim := strings.TrimSpace(string(data))
		if strings.HasPrefix(trim, "{") {
			trim = "[" + trim + "]"
		}
		if err := json.Unmarshal([]byte(trim), &reports); err != nil {
			t.Fatalf("checkov golden: %v", err)
		}
		for _, r := range reports {
			for _, f := range r.Results.Failed {
				out[f.CheckID+"|"+f.Resource] = true
			}
		}
	case "trivy":
		var rep struct {
			Results []struct {
				Target            string `json:"Target"`
				Misconfigurations []struct {
					ID     string `json:"ID"`
					Status string `json:"Status"`
					Cause  struct {
						Resource string `json:"Resource"`
					} `json:"CauseMetadata"`
				} `json:"Misconfigurations"`
			} `json:"Results"`
		}
		if err := json.Unmarshal(data, &rep); err != nil {
			t.Fatalf("trivy golden: %v", err)
		}
		for _, r := range rep.Results {
			for _, m := range r.Misconfigurations {
				if m.Status != "FAIL" {
					continue
				}
				res := m.Cause.Resource
				if res == "" {
					res = r.Target
				}
				out[m.ID+"|"+res] = true
			}
		}
	default:
		t.Fatalf("unknown golden tool %q", tool)
	}
	return out
}

// TestGoldenIntegrity: every golden file listed in expectations.yaml exists, matches sha256.txt and
// has a cmd.txt; every expectation names a lab weakness.
func TestGoldenIntegrity(t *testing.T) {
	var gf goldenFile
	loadYAML(t, "lab/golden/expectations.yaml", &gf)
	e := loadEstate(t)
	weak := map[string]bool{}
	for _, w := range e.Weaknesses {
		weak[w.ID] = true
	}
	if len(gf.Tools) == 0 {
		t.Fatal("lab/golden/expectations.yaml lists no tools")
	}
	for _, g := range gf.Tools {
		dir := filepath.Join(repoRoot, g.dir())
		if _, err := os.Stat(filepath.Join(dir, "cmd.txt")); err != nil {
			t.Errorf("%s: cmd.txt missing", g.dir())
		}
		sums := map[string]string{}
		raw, err := os.ReadFile(filepath.Join(dir, "sha256.txt"))
		if err != nil {
			t.Errorf("%s: sha256.txt missing", g.dir())
		}
		for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
			if f := strings.Fields(line); len(f) == 2 {
				sums[f[1]] = f[0]
			}
		}
		for _, f := range g.Files {
			data, err := os.ReadFile(filepath.Join(dir, f))
			if err != nil {
				t.Errorf("%s/%s: %v", g.dir(), f, err)
				continue
			}
			got := sha256.Sum256(data)
			if want := sums[f]; want != hex.EncodeToString(got[:]) {
				t.Errorf("%s/%s: sha256 %s, sha256.txt says %q (regenerate with lab/golden/regen.sh)", g.dir(), f, hex.EncodeToString(got[:]), want)
			}
		}
		if len(g.Detects) == 0 {
			t.Errorf("%s: no detections listed", g.Tool)
		}
		for _, d := range g.Detects {
			if !weak[d.Weakness] {
				t.Errorf("%s: %s is not a lab weakness", g.Tool, d.Weakness)
			}
			if d.Check == "" || d.Resource == "" || d.Canonical == "" {
				t.Errorf("%s %s: check, resource and canonical are required", g.Tool, d.Weakness)
			}
		}
		for w := range g.NotDetected {
			if !weak[w] {
				t.Errorf("%s not_detected: %s is not a lab weakness", g.Tool, w)
			}
		}
	}
}

type interopRow struct {
	tool, weakness, check, resource, canonical, got, outcome string
}

type interopTotals struct {
	tool, version                     string
	detects, mapped                   int
	fail, failMapped                  int
	unmappedChecks                    []string
	notDetected, notInHCL, weaknesses int
}

func TestGoldenScannerInterop(t *testing.T) {
	var gf goldenFile
	loadYAML(t, "lab/golden/expectations.yaml", &gf)
	var kg knownGaps
	loadYAML(t, "lab/known_gaps.yaml", &kg)

	failures := map[string]string{}
	var rows []interopRow
	var totals []interopTotals
	for _, g := range gf.Tools {
		home := t.TempDir()
		db := filepath.Join(home, "posture.db")
		cfg, err := os.ReadFile(filepath.Join(repoRoot, "lab", "local", "cloud-posture.lab.yaml"))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(home, "cloud-posture.yaml"), cfg, 0o644); err != nil {
			t.Fatal(err)
		}

		raw := map[string]bool{}
		args := []string{"--no-network", "ingest"}
		for _, f := range g.Files {
			p := filepath.Join(repoRoot, g.dir(), f)
			data, err := os.ReadFile(p)
			if err != nil {
				t.Fatal(err)
			}
			for k := range rawFailures(t, g.Tool, data) {
				raw[k] = true
			}
			args = append(args, p)
		}
		args = append(args, "--source", g.Tool, "-o", "json")
		cli(t, home, db, args...)

		var q struct {
			Rows [][]any `json:"rows"`
		}
		sql := fmt.Sprintf("SELECT check_id, COALESCE(resource_id,''), COALESCE(file,''), COALESCE(canonical_id,'') FROM findings WHERE status = 'FAIL' AND source = '%s'", g.Tool)
		if err := json.Unmarshal(cli(t, home, db, "--no-network", "query", "-f", "json", sql), &q); err != nil {
			t.Fatalf("%s: query: %v", g.Tool, err)
		}
		prefix := strings.ToUpper(g.Tool) + ":"
		tot := interopTotals{tool: g.Tool, version: g.Version, detects: len(g.Detects), notDetected: len(g.NotDetected), notInHCL: len(g.NotInLabHCL)}
		unmapped := map[string]bool{}
		type nf struct{ check, res, file, canon string }
		var found []nf
		for _, r := range q.Rows {
			s := func(i int) string { v, _ := r[i].(string); return v }
			found = append(found, nf{s(0), s(1), s(2), s(3)})
			tot.fail++
			if strings.HasPrefix(s(3), prefix) || s(3) == "" {
				unmapped[s(0)] = true
			} else {
				tot.failMapped++
			}
		}
		for c := range unmapped {
			tot.unmappedChecks = append(tot.unmappedChecks, c)
		}
		sort.Strings(tot.unmappedChecks)

		ws := map[string]bool{}
		for _, d := range g.Detects {
			ws[d.Weakness] = true
			if !raw[d.Check+"|"+d.Resource] {
				t.Errorf("%s %s: %s on %s is not a failed check in the raw golden %s (fix lab/golden/expectations.yaml or regenerate)", g.Tool, d.Weakness, d.Check, d.Resource, g.dir())
				continue
			}
			row := interopRow{tool: g.Tool, weakness: d.Weakness, check: d.Check, resource: d.Resource, canonical: d.Canonical}
			var gots []string
			for _, f := range found {
				if f.check == d.Check && (f.res == d.Resource || (f.res == "" && f.file == d.Resource)) {
					gots = append(gots, f.canon)
				}
			}
			sort.Strings(gots)
			row.got = strings.Join(gots, ", ")
			switch {
			case len(gots) == 0:
				row.outcome = "NOT INGESTED"
			case contains(gots, d.Canonical):
				row.outcome = "MAPPED"
				tot.mapped++
			case strings.HasPrefix(gots[0], prefix):
				row.outcome = "UNMAPPED"
			default:
				row.outcome = "MISMAPPED"
			}
			if row.outcome != "MAPPED" {
				key := fmt.Sprintf("golden:%s:%s:%s", g.Tool, d.Weakness, d.Check)
				failures[key] = fmt.Sprintf("%s %s on %s: %s (got %q, want %s)", g.Tool, d.Check, d.Resource, row.outcome, row.got, d.Canonical)
			}
			rows = append(rows, row)
		}
		tot.weaknesses = len(ws)
		totals = append(totals, tot)
	}

	report := renderInterop(rows, totals)
	t.Log("\n" + report)
	checkMappedFloor(t, totals)
	checkBenchmarkDoc(t, totals)
	if out := os.Getenv("GOLDEN_REPORT"); out != "" {
		if err := os.WriteFile(out, []byte(report), 0o644); err != nil {
			t.Errorf("GOLDEN_REPORT: %v", err)
		}
	}

	ids := make([]string, 0, len(failures))
	for id := range failures {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	if strict() {
		for _, id := range ids {
			t.Errorf("[strict] %s: %s", id, failures[id])
		}
		return
	}
	known := map[string]knownGap{}
	for _, g := range kg.Golden {
		known[g.ID] = g
	}
	for _, id := range ids {
		if g, ok := known[id]; ok {
			t.Logf("known gap %s (%s): %s", id, g.Owner, failures[id])
			continue
		}
		t.Errorf("NEW failure %s: %s (fix the mapping, or label it in lab/known_gaps.yaml golden: with an owner)", id, failures[id])
	}
	for _, g := range kg.Golden {
		if _, ok := failures[g.ID]; !ok {
			t.Errorf("known gap %s no longer reproduces: remove it from lab/known_gaps.yaml golden: (cause was: %s)", g.ID, g.Cause)
		}
	}
}

func contains(xs []string, x string) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}

func renderInterop(rows []interopRow, totals []interopTotals) string {
	var b strings.Builder
	b.WriteString("| tool | version | lab weaknesses detected | detections mapped to the expected canonical id | FAIL findings | catalog coverage (mapped / FAIL) | unmapped FAIL findings | distinct unmapped checks |\n|---|---|---|---|---|---|---|---|\n")
	for _, t := range totals {
		fmt.Fprintf(&b, "| %s | %s | %d (%d detections) | %d / %d (%s) | %d | %s (%d/%d) | %d | %d |\n",
			t.tool, t.version, t.weaknesses, t.detects, t.mapped, t.detects, pct(ratio(t.mapped, t.detects)),
			t.fail, pct(ratio(t.failMapped, t.fail)), t.failMapped, t.fail, t.fail-t.failMapped, len(t.unmappedChecks))
	}
	b.WriteString("\n| tool | weakness | native check | resource | expected canonical | nimbus canonical | outcome |\n|---|---|---|---|---|---|---|\n")
	for _, r := range rows {
		fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s | %s |\n", r.tool, r.weakness, r.check, r.resource, r.canonical, r.got, r.outcome)
	}
	for _, t := range totals {
		fmt.Fprintf(&b, "\nUnmapped %s checks (%d): %s\n", t.tool, len(t.unmappedChecks), strings.Join(t.unmappedChecks, ", "))
	}
	return b.String()
}
